"""Portable offline companion dashboard; no third-party scripts or services."""
from pathlib import Path
import pandas as pd,json
R=Path(__file__).resolve().parents[1]
def main():
 d=pd.read_csv(R/'data/processed/customers_features.csv')
 fields=['customer_id','age_band','gender','state','category','value_tier','history_band','purchase_amount_usd','annual_spend_proxy_usd','promo_exposed','loyalty_a','satisfied','segment']
 data=d[fields].to_dict('records')
 html=r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Customer Value | Founder Dashboard</title><style>
*{box-sizing:border-box}body{margin:0;background:#f1f5f9;color:#12263f;font:14px system-ui,Segoe UI,sans-serif}.wrap{max-width:1460px;margin:auto;padding:28px}header{display:flex;justify-content:space-between;gap:20px}h1{font-size:30px;margin:5px 0 10px;letter-spacing:-1px}.eyebrow{font-size:11px;letter-spacing:2px;color:#14757c;font-weight:800}p{line-height:1.5;color:#56677b}.controls{display:flex;flex-wrap:wrap;gap:14px;align-items:end;background:white;padding:15px;border-radius:12px;margin:20px 0}.controls label{display:grid;gap:5px;font-size:12px;color:#56677b}select,button{padding:9px;border:1px solid #d7e0ea;border-radius:6px;background:white;color:#12263f}button{cursor:pointer}.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin-bottom:18px}.kpi{padding:18px;background:#12263f;color:white;border-radius:10px}.kpi small{color:#b5c8dc}.num{font-size:28px;font-weight:700;margin-top:8px}.panels{display:grid;grid-template-columns:1fr 1fr;gap:18px}.panel{background:white;padding:22px;border:1px solid #e0e7ef;border-radius:12px;min-height:340px}h2{font-size:18px;margin:0}h3{font-size:14px}small{color:#65758a}svg{width:100%;height:auto}.muted{font-size:12px;color:#65758a}.bar{height:36px;background:#e7eef4;border-radius:5px;position:relative;margin:8px 0 18px}.fill{height:100%;border-radius:5px;background:#166e75;min-width:2px}.row{display:flex;justify-content:space-between;gap:8px;font-size:12px}.tiles{display:grid;grid-template-columns:repeat(12,1fr);gap:4px;margin-top:20px}.tile{aspect-ratio:1;border:0;border-radius:4px;padding:2px;font-size:11px;font-weight:700;position:relative}.tile:hover{outline:3px solid #d2a348;z-index:1}.stack{height:30px;display:flex;margin:7px 0 14px;border-radius:4px;overflow:hidden}.legend{display:flex;gap:13px;font-size:11px;margin-top:10px}.swatch{display:inline-block;width:10px;height:10px;margin-right:4px}.note{background:#e6f1f0;border-left:3px solid #166e75;padding:14px;line-height:1.6;margin-top:18px;font-size:12px}.detail{min-height:55px;background:#f4f7fa;padding:10px;margin-top:12px;border-radius:5px}table{border-collapse:collapse;width:100%;font-size:12px}td,th{text-align:left;border-bottom:1px solid #e5ebf1;padding:7px}footer{margin:20px 0;color:#65758a;font-size:12px}.empty{padding:40px;text-align:center;color:#65758a}@media(max-width:850px){.panels{grid-template-columns:1fr}.kpis{grid-template-columns:repeat(2,1fr)}.wrap{padding:15px}header{display:block}}
</style></head><body><div class="wrap"><header><div><div class="eyebrow">D2C FASHION / CUSTOMER INTELLIGENCE</div><h1>Decoding customer value</h1><p>A founder's view of value, promotional exposure and repeat-purchase signals.</p></div><div class="muted">3,900-customer snapshot<br>No timestamps or churn labels<br>USD · United States</div></header>
<div class="controls"><label>Product category<select id="category"></select></label><label>State<select id="state"></select></label><label>Age group<select id="age_band"></select></label><label>Gender<select id="gender"></select></label><button id="reset">Reset filters</button><button id="download">Export filtered customers</button><small>All four panels respond to filters. Hover over a state for detail.</small></div><div class="kpis" id="kpis"></div><div class="panels"><section class="panel"><h2>01 / Customer value pyramid</h2><p class="muted">Annual spend proxy defines tiers. Recorded sales show their observed contribution.</p><div id="pyramid"></div></section><section class="panel"><h2>02 / Promo exposure × repeat cadence</h2><p class="muted">Value tiers are the comparison segments. Bubble area reflects recorded sales.</p><div id="scatter"></div></section><section class="panel"><h2>03 / Geographic opportunity map</h2><p class="muted">US state tile map; position is schematic. Darker = higher smoothed full-price spend per customer.</p><div class="tiles" id="map"></div><div class="detail" id="stateDetail">Hover over a state to inspect sample size, spend and promo exposure.</div><small>Alaska and Hawaii are inset. Blank tiles have no customers under current filters.</small></section><section class="panel"><h2>04 / Category history mix</h2><p class="muted">Entry-point / retention proxy. This is a cross-section, not an observed purchase journey.</p><div id="funnel"></div><div class="legend"><span><i class="swatch" style="background:#b8c5d7"></i>Low: 0–10</span><span><i class="swatch" style="background:#6984ad"></i>Mid: 11–25</span><span><i class="swatch" style="background:#166e75"></i>High: 26+</span></div></section></div>
<div class="note"><b>Read these metrics correctly.</b> Repeat cadence proxy = previous purchases ≥26 and stated frequency ≥12/year. It is not a retention rate. Promo exposure records the current purchase only; it does not establish dependency. Annual spend proxy = current purchase amount × stated annual frequency, not forecast revenue or CLV. The high tier and repeat proxy both use cadence, so their association is partly constructed. State rankings are test hypotheses, not evidence of incremental acquisition returns.</div><footer>Prepared for Soumabha Bhim · Source: supplied Dataset.csv · Local-only companion to the Power BI project · No external resources</footer></div><script>
const DATA=__DATA__;let filtered=DATA;const colors=['#166e75','#6984ad','#b8c5d7'];const sum=(a,k)=>a.reduce((s,x)=>s+x[k],0),mean=(a,k)=>a.length?sum(a,k)/a.length:0,usd=n=>'$'+n.toLocaleString('en-US',{maximumFractionDigits:0}),pct=n=>(100*n).toFixed(1)+'%';
const groups=(a,k)=>Object.groupBy(a,x=>x[k]);const escape=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('"','&quot;');
for(const k of ['category','state','age_band','gender']){const e=document.getElementById(k);e.innerHTML='<option value="">All</option>'+[...new Set(DATA.map(x=>x[k]))].sort().map(x=>`<option>${escape(x)}</option>`).join('');e.addEventListener('change',render)}
const tiles=[['Alaska','AK',0,0],['Maine','ME',11,0],['Vermont','VT',9,1],['New Hampshire','NH',10,1],['Washington','WA',0,2],['Idaho','ID',1,2],['Montana','MT',2,2],['North Dakota','ND',3,2],['Minnesota','MN',4,2],['Illinois','IL',5,2],['Wisconsin','WI',6,2],['Michigan','MI',7,2],['New York','NY',9,2],['Massachusetts','MA',10,2],['Rhode Island','RI',11,2],['Oregon','OR',0,3],['Nevada','NV',1,3],['Wyoming','WY',2,3],['South Dakota','SD',3,3],['Iowa','IA',4,3],['Indiana','IN',5,3],['Ohio','OH',6,3],['Pennsylvania','PA',8,3],['New Jersey','NJ',9,3],['Connecticut','CT',10,3],['California','CA',0,4],['Utah','UT',1,4],['Colorado','CO',2,4],['Nebraska','NE',3,4],['Missouri','MO',4,4],['Kentucky','KY',5,4],['West Virginia','WV',6,4],['Virginia','VA',7,4],['Maryland','MD',8,4],['Delaware','DE',9,4],['Arizona','AZ',1,5],['New Mexico','NM',2,5],['Kansas','KS',3,5],['Arkansas','AR',4,5],['Tennessee','TN',5,5],['North Carolina','NC',6,5],['South Carolina','SC',7,5],['Oklahoma','OK',3,6],['Louisiana','LA',4,6],['Mississippi','MS',5,6],['Alabama','AL',6,6],['Georgia','GA',7,6],['Hawaii','HI',0,7],['Texas','TX',3,7],['Florida','FL',8,7]];
function render(){filtered=DATA.filter(x=>['category','state','age_band','gender'].every(k=>!document.getElementById(k).value||x[k]===document.getElementById(k).value));const a=filtered,n=a.length,sales=sum(a,'purchase_amount_usd');document.getElementById('kpis').innerHTML=[['Customers',n.toLocaleString()],['Recorded sales',usd(sales)],['Sales with promo flag',sales?pct(sum(a.filter(x=>x.promo_exposed),'purchase_amount_usd')/sales):'—'],['Repeat cadence proxy',n?pct(mean(a,'loyalty_a')):'—']].map(([l,v])=>`<div class="kpi"><small>${l}</small><div class="num">${v}</div></div>`).join('');
 const tiers=['High','Core','Developing'].map((k,i)=>({k,i,rows:a.filter(x=>x.value_tier===k)}));document.getElementById('pyramid').innerHTML=tiers.map(t=>`<div class="row"><b>${t.k}</b><span>${t.rows.length.toLocaleString()} customers · ${usd(sum(t.rows,'purchase_amount_usd'))} · ${sales?pct(sum(t.rows,'purchase_amount_usd')/sales):'—'} of sales</span></div><div class="bar"><div class="fill" style="width:${n?100*t.rows.length/n:0}%;background:${colors[t.i]}"></div></div>`).join('')+'<small>High ≥$1,924; Core $572–&lt;$1,924; Developing &lt;$572 annual spend proxy. Fixed thresholds.</small>';
 let svg='<svg viewBox="0 0 580 285" role="img" aria-label="Promo share versus repeat cadence proxy scatterplot">';for(let i=0;i<=4;i++){const x=55+i*120,y=235-i*50;svg+=`<line x1="55" y1="${y}" x2="535" y2="${y}" stroke="#e4eaf1"/><text x="45" y="${y+4}" text-anchor="end" font-size="10">${i*25}%</text><text x="${x}" y="253" text-anchor="middle" font-size="10">${i*25}%</text>`}svg+='<text x="285" y="279" text-anchor="middle" font-size="11">Customers with promotion flag</text><text x="10" y="140" transform="rotate(-90 10 140)" text-anchor="middle" font-size="11">Repeat cadence proxy</text>';
 for(const t of tiers){if(!t.rows.length)continue;let x=55+480*mean(t.rows,'promo_exposed'),y=235-200*mean(t.rows,'loyalty_a'),r=40*Math.sqrt(sum(t.rows,'purchase_amount_usd')/Math.max(1,sales));svg+=`<circle cx="${x}" cy="${y}" r="${r}" fill="${colors[t.i]}" fill-opacity=".8"><title>${t.k}: ${pct(mean(t.rows,'promo_exposed'))} promo; ${pct(mean(t.rows,'loyalty_a'))} repeat proxy; ${usd(sum(t.rows,'purchase_amount_usd'))} sales</title></circle><text x="${Math.min(480,x+r+5)}" y="${y+[-35,22,-8][t.i]}" font-size="12">${t.k}</text>`}document.getElementById('scatter').innerHTML=svg+'</svg>';
 const states=groups(a,'state'),national=mean(a.map(x=>({...x,fp:x.purchase_amount_usd*(1-x.promo_exposed)})),'fp');document.getElementById('map').innerHTML=tiles.map(([name,abbr,x,y])=>{const rows=states[name]||[],fp=sum(rows.filter(r=>!r.promo_exposed),'purchase_amount_usd'),score=(fp+50*national)/(rows.length+50),ratio=national?Math.max(0,Math.min(1,score/(national*1.5))):0;return `<button class="tile" data-state="${name}" style="grid-column:${x+1};grid-row:${y+1};background:${rows.length?`rgb(${Math.round(226-204*ratio)},${Math.round(238-128*ratio)},${Math.round(240-123*ratio)})`:'#f3f5f7'};color:${ratio>.7&&rows.length?'white':'#12263f'}" aria-label="${name}">${abbr}</button>`}).join('');for(const e of document.querySelectorAll('.tile')){const show=()=>{const rows=states[e.dataset.state]||[];document.getElementById('stateDetail').textContent=rows.length?`${e.dataset.state}: ${rows.length} customers | AOV ${usd(mean(rows,'purchase_amount_usd'))} | Promo ${pct(mean(rows,'promo_exposed'))} | Full-price spend/customer ${usd(sum(rows.filter(r=>!r.promo_exposed),'purchase_amount_usd')/rows.length)}`:e.dataset.state+': no customers under current filters'};e.addEventListener('mouseenter',show);e.addEventListener('focus',show)}
 const bands=['Low history (0-10)','Mid history (11-25)','High history (26+)'];document.getElementById('funnel').innerHTML=['Clothing','Accessories','Footwear','Outerwear'].map(k=>{const rows=a.filter(x=>x.category===k);return `<div class="row"><b>${k}</b><span>${rows.length} customers</span></div><div class="stack">`+bands.map((b,i)=>{const m=rows.filter(x=>x.history_band===b).length;return `<div style="width:${rows.length?100*m/rows.length:0}%;background:${['#b8c5d7','#6984ad','#166e75'][i]}" title="${b}: ${m} customers, ${rows.length?pct(m/rows.length):'0%'}"></div>`}).join('')+'</div>'}).join('');}
 document.getElementById('reset').onclick=()=>{for(const k of ['category','state','age_band','gender'])document.getElementById(k).value='';render()};document.getElementById('download').onclick=()=>{const keys=Object.keys(DATA[0]),q=v=>'"'+String(v).replaceAll('"','""')+'"',csv=keys.join(',')+'\n'+filtered.map(x=>keys.map(k=>q(x[k])).join(',')).join('\n'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv'})),a=document.createElement('a');a.href=url;a.download='filtered_customers.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};render();
</script></body></html>'''
 out=R/'dashboard/Founder_Dashboard.html';out.parent.mkdir(exist_ok=True)
 out.write_text(html.replace('__DATA__',json.dumps(data,separators=(',',':'))),encoding='utf-8')
 docs=R/'docs';docs.mkdir(exist_ok=True)
 (docs/'index.html').write_text(out.read_text(encoding='utf-8'),encoding='utf-8')
 (docs/'.nojekyll').write_text('',encoding='utf-8')
 print('Offline dashboard generated:',len(data),'customers')
if __name__=='__main__':main()
